SELECT 'gongkao', '行文结构框架', 'kp-sl-essay-structure', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "大作文：行文结构框架"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "五段三分式。这是公考最高效、最稳妥的八股文结构。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、五段三分式拆解"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一段（凤头）：引出背景，点明核心问题，抛出【总论点】。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二段（分论点1）：分论点句 + 举例/说理 + 小结。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第三段（分论点2）：分论点句 + 举例/说理 + 小结。 (注意与分论点1保持句式对仗)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第四段（分论点3）：分论点句 + 举例/说理 + 小结。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第五段（豹尾）：总结全文，升华主题，呼应开头。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、分论点怎么找？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "分论点绝对不能是自己瞎想的！必须从前面的【小题（归纳概括、综合分析）】的答案中去提取。前面的小题找出了原因1、2、3，你的大作文分论点就是解决这1、2、3的对策。"}]}]}$$ AS jsonb), NULL, '行文结构框架的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "大作文", "行文结构"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_essay_structure", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
